"""
Build the waw workflow notebooks with nbformat.

01/02 are waw-native, self-contained analysis workflows in the same vein as
workflows/w90tutorial/: converged Quantum ESPRESSO (PseudoDojo pseudos) ->
waw's own `.nnkp` -> pw2wannier90 overlaps -> waw ASE-native `wannierize` ->
waw analysis (here, `analysis.surface`'s Green's-function decimation). No
`wannier90.x` and no `.win`/`.chk`; each does its own fresh DFT run rather
than reading a precomputed fixture.

Run `python _generate.py` to (re)write the .ipynb files, then execute them
with the same recipe as workflows/w90tutorial/:
    module load quantum-espresso/7.3.1-gcc-13.2.0-6jwmo4k
    python -m nbconvert --to notebook --execute --inplace --kernel=waw NN_*.ipynb
"""
import nbformat as nbf
from pathlib import Path

HERE = Path(__file__).parent
KERNEL = {"kernelspec": {"name": "waw", "display_name": "waw"},
          "language_info": {"name": "python"}}


def make(path, cells):
    nb = nbf.v4.new_notebook(metadata=KERNEL)
    nb.cells = [nbf.v4.new_markdown_cell(s) if t == "md" else nbf.v4.new_code_cell(s)
                for t, s in cells]
    nbf.write(nb, str(HERE / path))
    print("wrote", path)


SETUP = """\
import os, sys, pathlib
import numpy as np
import matplotlib.pyplot as plt

HERE = pathlib.Path.cwd()
REPO = HERE
while not (REPO / 'waw').exists() and REPO != REPO.parent:
    REPO = REPO.parent
sys.path.insert(0, str(REPO))

import waw
from waw.interfaces import quantum_espresso as qe   # the direct-input QE driver
from waw.interfaces.ase.driver import wannierize
from waw.units import BOHR_TO_ANG, HARTREE_TO_EV, EV_TO_HARTREE
from waw.vis import plot_bands, BandSeries

PSEUDO_DIR = REPO / 'workflows' / 'pseudos'   # shared across workflows/, not notebooks/-specific
NCORES = 16
waw.set_num_threads(NCORES)
print('waw', 'threads =', waw.get_num_threads(), '| repo', REPO)"""


