# ==========================================================================
# 4. Comparing gauge-optimization methods on a genuinely hard case
# ==========================================================================
optim_compare = [
    ("md", "# Comparing Wannierisation minimizers — SGD, Adam, CG, L-BFGS, DIIS, RTR\n"
     "\n"
     "`core.optim.minimize_spread` minimizes the Marzari-Vanderbilt spread "
     "functional $\\Omega(U)$ over the unitary gauge $U(k) \\in U(n_w)$ using "
     "one of six native Riemannian optimizers (no `torch.optim`/`geoopt` — "
     "neither supports the complex128 QR retraction this project relies "
     "on):\n"
     "\n"
     "- **SGD** — steepest descent, Armijo backtracking line search.\n"
     "- **Adam** — Riemannian Adam (Bécigneul & Ganea, ICLR 2019), momentum "
     "and per-element scaling carried in the tangent space.\n"
     "- **CG** — nonlinear conjugate gradients (Fletcher-Reeves), matching "
     "wannier90's own minimizer; a parabolic (not Armijo) line search fits "
     "the exact quadratic through the current point, its slope, and one "
     "trial step.\n"
     "- **L-BFGS** — quasi-Newton, two-loop recursion over the last few "
     "curvature pairs $(s_i, y_i)$ approximating the inverse-Hessian action "
     "on the gradient, same parabolic line search as CG.\n"
     "- **DIIS** — Pulay-mixing (subspace acceleration): each iterate's "
     "Riemannian gradient serves as its DIIS \"error vector\" (the residual "
     "of the fixed-point problem $\\nabla\\Omega=0$); the extrapolated "
     "ambient combination of recent iterates is re-projected onto $U(n_w)$ "
     "(nearest-unitary/polar retraction) and only accepted if it beats a "
     "safeguarded steepest-descent step from the same point.\n"
     "- **RTR** — Riemannian trust-region (Absil, Baker & Gallivan, "
     "*Found. Comput. Math.* **7**, 303 (2007)), the only **second-order** "
     "method here: builds a local quadratic model from the Riemannian "
     "gradient and an (approximate) Riemannian Hessian-vector product — "
     "via double backward through the very same autodiff'd $\\Omega(U)$ "
     "the gradient already uses, no hand-derived second derivative needed "
     "— approximately minimizes it within a trust region via truncated CG "
     "(Steihaug-Toint), and accepts/rejects the step while growing/"
     "shrinking the trust radius from the ratio of actual to predicted "
     "decrease.\n"
     "\n"
     "All six share the exact same Riemannian-gradient/QR-retraction "
     "machinery (`core.optim._riemannian_gradient`/`_qr_retract`) and the "
     "same autodiff'd $\\Omega(U)$ forward pass — only the search direction "
     "and step-size logic differ.\n"
     "\n"
     "**The hard case**: `w90tutorial/27_silicon_scdm`'s \"gaussian\" "
     "SCDM-entanglement variant — 4 MLWFs built from Si's 4 lowest "
     "*conduction* bands (`scdm_entanglement='gaussian', mu=12.5 eV, "
     "sigma=2.0 eV`), an exactly-isolated 4-band manifold (no "
     "disentanglement freedom at all — every candidate band survives the "
     "window at every k, so the whole gauge problem reduces to spread "
     "minimization alone). That earlier notebook found this a genuinely "
     "slow, asymmetric optimization landscape with more than one local "
     "minimum: real `wannier90.x` itself needs ~3000 iterations here too "
     "(confirmed from its own `.wout` log), and plain optimizers without "
     "`guiding_centres` converge to a different, WORSE local minimum than "
     "the one matching wannier90.x's reference value "
     "($\\Omega_\\mathrm{total}=21.648613\\,\\mathrm{\\mathring{A}}^2$) — "
     "exactly the kind of case that can tell optimizers apart."),
    ("code", SETUP),
    ("md", "### 1. Structure and DFT — same recipe as tutorial 27's `si_gau`\n"
     "Bulk diamond Si, $a=5.43$ Å. `outer_window=(6.5, 17.0)` eV excludes "
     "the valence manifold entirely (Si's own valence tops out at 6.23 eV, "
     "conduction bottoms out at 6.94 eV) — exactly 4 candidate bands "
     "survive at every k, so disentanglement is trivial and every "
     "optimizer is solving the identical, fixed 4-band gauge problem."),
    ("code",
     "from ase.build import bulk\n"
     "from waw.core.optim import minimize_spread\n"
     "\n"
     "atoms = bulk('Si', 'diamond', a=5.43)\n"
     "MP_GRID = (4, 4, 4)\n"
     "WORK = HERE / 'runs' / 'optim_compare'\n"
     "\n"
     "ov = qe.generate_overlaps(\n"
     "    atoms, MP_GRID, WORK, 'si_gau',\n"
     "    ecutwfc=40, scf_kpts=(8, 8, 8), nbnd=8, num_wann=4,\n"
     "    scdm_entanglement='gaussian', scdm_mu=12.5, scdm_sigma=2.0,\n"
     "    pseudopotentials={'Si': 'Si.upf'},\n"
     "    pseudo_dir=PSEUDO_DIR, ncores=NCORES, rerun_scf=False,\n"
     ")\n"
     "print('overlaps ready, nk =', len(ov['kpts']))"),
    ("md", "### 2. Disentangle once, then hand the SAME initial gauge to every optimizer\n"
     "Disentanglement (subspace selection) is identical regardless of which "
     "gauge optimizer runs afterwards, so it's done once here and every "
     "optimizer starts from the exact same `U_init` — an apples-to-apples "
     "comparison, not five independent Wannierisations that happen to start "
     "from re-derived-but-nominally-equal subspaces."),
    ("code",
     "import torch\n"
     "from waw.core.disentangle import disentangle\n"
     "from waw.core.init import svd_init\n"
     "from waw.core.spread import rotate_overlaps\n"
     "from waw.interfaces.ase.driver import build_wannier_data\n"
     "from waw.interfaces.ase.structure import recip_lattice\n"
     "\n"
     "wdata = build_wannier_data(\n"
     "    recip_lattice(atoms), ov['kpts'], ov['mmn'], ov['amn'], ov['eig'],\n"
     "    ov['nnkpts'], ov['g_vectors'],\n"
     ")\n"
     "dis = disentangle(wdata.Mmn, wdata.eig, wdata.wb, wdata.kb_idx, nw=4, Amn=wdata.Amn,\n"
     "                  outer_window=(6.5 * EV_TO_HARTREE, 17.0 * EV_TO_HARTREE))\n"
     "Mmn_opt = rotate_overlaps(dis.V, wdata.Mmn, wdata.kb_idx)   # (nk, nnb, nw, nw), projected by V\n"
     "Amn_sub = torch.einsum('kmi,kmj->kij', dis.V.conj(), wdata.Amn)\n"
     "U_init = svd_init(Amn_sub)\n"
     "print('U_init built from the shared disentangled subspace:', U_init.shape)"),
    ("md", "### 3. Run all six optimizers from the same `U_init`, `guiding_centres=True`\n"
     "`lr` plays a different role per optimizer: a fixed Riemannian-Adam "
     "step vs. a line-search trial-step length for the other four. Unlike "
     "the easier valence-only Silicon case (`test_cg_is_insensitive_to_"
     "trial_step` in `tests/test_init_optim.py`), this harder conduction-"
     "manifold landscape turns out NOT to be trial-step-insensitive: CG "
     "with `lr=1.0` (a value that works fine on the easy case) lands "
     "6 Ų above wannier90.x's own reference here, while `lr=3e-2` "
     "(this notebook's own tutorial-27 recipe never overrides `lr`, "
     "i.e. uses this same default) reaches it — a genuine, worth-noting "
     "landscape-dependence, not a fixed rule of thumb. All five optimizers "
     "use `lr=3e-2` below for a fair, uniform comparison."),
    ("code",
     "import time\n"
     "\n"
     "W90_REF = 21.648613   # Ang^2, wannier90.x's own reference for this exact system\n"
     "OPTIMIZERS = [('sgd', 3e-2), ('adam', 3e-2), ('cg', 3e-2), ('lbfgs', 3e-2),\n"
     "              ('diis', 3e-2), ('rtr', 0.1)]   # rtr's lr is a trust-region radius, not a step length\n"
     "\n"
     "results = {}\n"
     "for name, lr in OPTIMIZERS:\n"
     "    t0 = time.time()\n"
     "    res = minimize_spread(\n"
     "        U_init, Mmn_opt, wdata.wb, wdata.bvecs, wdata.kb_idx,\n"
     "        optimizer=name, lr=lr, n_iter=3000, conv_tol=1e-10, conv_window=10,\n"
     "        guiding_centres=True,\n"
     "    )\n"
     "    elapsed = time.time() - t0\n"
     "    results[name] = (res, elapsed)\n"
     "    omega_ang2 = res.Omega * BOHR_TO_ANG**2\n"
     "    print(f'{name:6s}: Omega={omega_ang2:9.4f} Ang^2  '\n"
     "          f'iters={len(res.history):5d}  converged={res.converged!s:5s}  '\n"
     "          f'time={elapsed:6.2f}s')"),
    ("md", "### 4. Convergence curves"),
    ("code",
     "fig, ax = plt.subplots(figsize=(7, 4.5), dpi=150)\n"
     "for name, _ in OPTIMIZERS:\n"
     "    res, _ = results[name]\n"
     "    omega_hist = np.array(res.history) * BOHR_TO_ANG**2\n"
     "    ax.semilogy(np.arange(len(omega_hist)), omega_hist - W90_REF + 1e-6, label=name)\n"
     "ax.axhline(1e-6, color='0.6', lw=0.7, ls=':')\n"
     "ax.set_xlabel('iteration'); ax.set_ylabel(r'$\\Omega - \\Omega_{W90}$ (Ang$^2$)')\n"
     "ax.set_title('Silicon conduction-manifold SCDM — optimizer convergence')\n"
     "ax.legend(); fig.tight_layout()"),
    ("md", "### 5. Summary table"),
    ("code",
     "print(f'{\"optimizer\":8s} {\"Omega (Ang^2)\":>14s} {\"iters\":>7s} '\n"
     "      f'{\"converged\":>10s} {\"time (s)\":>9s} {\"vs W90\":>10s}')\n"
     "for name, _ in OPTIMIZERS:\n"
     "    res, elapsed = results[name]\n"
     "    omega_ang2 = res.Omega * BOHR_TO_ANG**2\n"
     "    print(f'{name:8s} {omega_ang2:14.6f} {len(res.history):7d} '\n"
     "          f'{str(res.converged):>10s} {elapsed:9.2f} {omega_ang2 - W90_REF:+10.4f}')"),
    ("md", "### 6. Without `guiding_centres`\n"
     "Tutorial 27's original notebook found that plain optimizers can land "
     "in a different, worse local minimum on this system without "
     "`guiding_centres`. Re-running without it, starting from the exact "
     "same shared `U_init` used above, isolates whether that's a "
     "`guiding_centres` effect specifically, or something else about this "
     "landscape."),
    ("code",
     "results_noguide = {}\n"
     "for name, lr in OPTIMIZERS:\n"
     "    res = minimize_spread(\n"
     "        U_init, Mmn_opt, wdata.wb, wdata.bvecs, wdata.kb_idx,\n"
     "        optimizer=name, lr=lr, n_iter=3000, conv_tol=1e-10, conv_window=10,\n"
     "        guiding_centres=False,\n"
     "    )\n"
     "    results_noguide[name] = res\n"
     "    omega_ang2 = res.Omega * BOHR_TO_ANG**2\n"
     "    print(f'{name:6s} (no guiding_centres): Omega={omega_ang2:9.4f} Ang^2  '\n"
     "          f'(with guiding_centres: {results[name][0].Omega * BOHR_TO_ANG**2:.4f})')"),
    ("md", "**Takeaway.** On this particular comparison (identical shared "
     "`U_init`, uniform `lr`), `guiding_centres` turns out to change very "
     "little — every optimizer's final Omega moves by well under "
     "0.2 Ų either way. The real fault line is between optimizer FAMILIES: "
     "**CG and Adam** reach wannier90.x's reference "
     "($21.648613\\,\\mathrm{\\mathring{A}}^2$) to within "
     "$0.1$-$0.4\\,\\mathrm{\\mathring{A}}^2$, while **SGD, L-BFGS, DIIS, "
     "and RTR** all settle into a distinctly different, shallower local "
     "minimum around $28.3$-$28.7\\,\\mathrm{\\mathring{A}}^2$ instead. "
     "That's not a coincidence for the first three: SGD's step *is* "
     "Armijo-backtracked steepest descent, and this notebook's L-BFGS/DIIS "
     "both fall back to exactly that same Armijo steepest-descent step "
     "whenever their own candidate step fails to lower Omega (L-BFGS: an "
     "ill-scaled quasi-Newton direction; DIIS: a Pulay-extrapolated point "
     "that doesn't improve on it) — so all three inherit steepest "
     "descent's basin of attraction on this landscape. RTR's presence in "
     "the same basin is the more surprising result: it never falls back to "
     "steepest descent at all (a rejected trust-region step just shrinks "
     "the radius and retries from the same point) and uses genuine "
     "second-order curvature information, yet it still converges — "
     "extremely fast (~110 iterations, a couple of seconds, using real "
     "Hessian-vector products) — to the *same* shallower minimum SGD/"
     "L-BFGS/DIIS find, not CG/Adam's deeper one. That's a real, general "
     "lesson about nonconvex optimization landscapes, not a bug in any one "
     "method: a locally accurate, fast-converging optimizer (RTR, and "
     "L-BFGS once its steps are safeguarded) reaches whichever local "
     "minimum's basin of attraction it started in *efficiently* — it has "
     "no special ability to escape a bad basin just because it's a better "
     "local method. Only CG's periodic steepest-descent restarts and "
     "parabolic line search, and Adam's momentum, happen to wander far "
     "enough off the straight-downhill path from this particular `U_init` "
     "to fall into the deeper basin instead. Which basin a run lands in "
     "here is decided by the optimizer's *trajectory*, not by how good it "
     "is at locally minimizing once it's near a minimum."),
]

# ==========================================================================
# 5. Comparing localization functionals: Marzari-Vanderbilt, Stengel-
#    Spaldin, Pipek-Mezey
# ==========================================================================
functional_compare = [
    ("md", "# Comparing localization functionals — MV, Stengel-Spaldin, Pipek-Mezey\n"
     "\n"
     "`core.optim.minimize_spread` doesn't have to minimize the ordinary "
     "Marzari-Vanderbilt (MV) spread $\\Omega$ — any differentiable "
     "$\\Omega(U)$ works, since every optimizer just autodiffs whatever "
     "forward function it's handed. This notebook compares three:\n"
     "\n"
     "- **MV** (Marzari & Vanderbilt, PRB **56**, 12847 (1997)) — the "
     "default everywhere else in this project: minimize the total spread "
     "$\\sum_n \\langle r^2\\rangle_n - \\langle r\\rangle_n^2$.\n"
     "- **SS** (Stengel & Spaldin, PRB **73**, 075121 (2006)) — an "
     "alternative $\\Omega_D$ (a k-averaged variance of $\\tilde M_{nn}$ "
     "instead of MV's branch-cut-sensitive $-\\mathrm{Im}\\ln \\tilde "
     "M_{nn}$ residual); $\\Omega_I$/$\\Omega_{OD}$ are identical to MV's "
     "own (`use_ss_functional=True`, already used by tutorial36).\n"
     "- **PM** (Pipek & Mezey, *J. Chem. Phys.* **90**, 4916 (1989)), NEW "
     "this notebook — a completely different localization *criterion*: "
     "instead of minimizing real-space spread, **maximize atomic "
     "character** — $\\Omega_\\mathrm{PM} = -\\sum_n\\sum_A Q_A[n]^2$, "
     "where $Q_A[n]$ is Wannier function $n$'s Mulliken charge on atom "
     "$A$ (built from `pw2wannier90`'s `atom_proj_ext` atomic-pseudo-"
     "orbital overlaps, `core.spread.compute_pm_spread` — new capability). "
     "PM orbitals aren't necessarily compact in space at all; they're "
     "compact in *which atoms* they sit on.\n"
     "\n"
     "**Not implemented**: Edmiston-Ruedenberg (maximize each orbital's "
     "Coulomb self-repulsion $\\iint |w_n(r)|^2|w_n(r')|^2/|r-r'|\\,dr\\,dr'$) "
     "— a real, classic alternative, but it needs a genuine real-space/"
     "reciprocal-Coulomb-kernel machinery this project's overlap-matrix-"
     "only ($M_{mn}$/$A_{mn}$) pipeline doesn't have; not attempted rather "
     "than shipped half-validated."),
    ("code", SETUP),
    ("md", "### 1. Structure, DFT, and atomic projectors — same recipe as\n"
     "`w90tutorial/35_silicon_atom_proj_ext`: bulk diamond Si, "
     "`atom_proj_ext=True` reads the pseudopotential's own $s$/$p$ "
     "pseudo-atomic-orbitals back out as the trial projections, giving "
     "`Aat` — the SAME tensor PM's Mulliken charges are built from — for "
     "free alongside the ordinary `Amn`. `proj_min`/`proj_max` "
     "(projectability) plus a loose energy window disentangle 40 "
     "candidate bands down to 8 target MLWFs (4 valence + 4 low "
     "conduction, matching the s+p atomic character of 2 Si atoms)."),
    ("code",
     "from ase.build import bulk\n"
     "import torch\n"
     "from waw.core.disentangle import disentangle\n"
     "from waw.core.init import svd_init\n"
     "from waw.core.spread import rotate_overlaps, compute_pm_spread\n"
     "from waw.core.optim import minimize_spread\n"
     "from waw.interfaces.ase.driver import build_wannier_data\n"
     "from waw.interfaces.ase.structure import recip_lattice\n"
     "from waw.interfaces.quantum_espresso.upf import (\n"
     "    read_pswfc, write_atom_proj_ext, atom_proj_column_atoms)\n"
     "\n"
     "atoms = bulk('Si', 'diamond', a=5.43)\n"
     "MP_GRID = (6, 6, 6)\n"
     "WORK = HERE / 'runs' / 'functional_compare'\n"
     "EXT_DIR = WORK / 'ext_proj'\n"
     "\n"
     "radial = read_pswfc(PSEUDO_DIR / 'Si.upf')\n"
     "write_atom_proj_ext(EXT_DIR, {'Si': radial})\n"
     "atom_index = torch.tensor(atom_proj_column_atoms(atoms, {'Si': radial}))\n"
     "print('l channels in Si.upf:', sorted(radial), '-> atom_index:', atom_index.tolist())\n"
     "\n"
     "ov = qe.generate_overlaps(\n"
     "    atoms, MP_GRID, WORK, 'si_pm',\n"
     "    ecutwfc=40, scf_kpts=(8, 8, 8), nbnd=40, num_wann=8,\n"
     "    atom_proj_ext=True, atom_proj_dir=EXT_DIR,\n"
     "    pseudopotentials={'Si': 'Si.upf'}, pseudo_dir=PSEUDO_DIR, ncores=NCORES,\n"
     "    rerun_scf=False,\n"
     ")\n"
     "print('overlaps ready, nk =', len(ov['kpts']))"),
    ("md", "### 2. Disentangle once, then hand the SAME initial gauge to every functional\n"
     "Same reasoning as the optimizer-comparison notebook: an "
     "apples-to-apples comparison needs a shared `U_init`, not three "
     "independent Wannierisations that happen to start from nominally "
     "equal subspaces. `Aat_sub` is `Amn` (here, atomic-orbital overlaps, "
     "not SCDM/analytic trial functions) projected into the disentangled "
     "subspace the same way `Mmn_opt` is."),
    ("code",
     "wdata = build_wannier_data(\n"
     "    recip_lattice(atoms), ov['kpts'], ov['mmn'], ov['amn'], ov['eig'],\n"
     "    ov['nnkpts'], ov['g_vectors'],\n"
     ")\n"
     "dis = disentangle(\n"
     "    wdata.Mmn, wdata.eig, wdata.wb, wdata.kb_idx, nw=8, Amn=wdata.Amn,\n"
     "    proj_min=0.01, proj_max=0.95, frozen_window=(-1.0e6, 8.7 * EV_TO_HARTREE),\n"
     "    n_iter=1000, conv_tol=1e-10,\n"
     ")\n"
     "print(f'Omega_I = {dis.omega_i * BOHR_TO_ANG**2:.4f} Ang^2  (converged: {dis.converged})')\n"
     "\n"
     "Mmn_opt = rotate_overlaps(dis.V, wdata.Mmn, wdata.kb_idx)\n"
     "Aat_sub = torch.einsum('kmi,kmj->kij', dis.V.conj(), wdata.Amn)   # atomic-orbital overlaps, same subspace\n"
     "U_init = svd_init(Aat_sub)\n"
     "print('U_init:', U_init.shape)"),
    ("md", "### 3. Optimize MV, SS, and PM from the same `U_init`\n"
     "All three via `optimizer='cg'` (this project's own default); PM's "
     "`Omega`/centres in the returned `SpreadResult` are still the "
     "ordinary MV ones evaluated at the PM-optimized `U_final` (PM has no "
     "spread decomposition of its own), so the same `.Omega` field is a "
     "fair like-for-like comparison across all three."),
    ("code",
     "COMMON = dict(optimizer='cg', lr=1.0, n_iter=1000, conv_tol=1e-10, conv_window=5)\n"
     "\n"
     "res_mv = minimize_spread(U_init, Mmn_opt, wdata.wb, wdata.bvecs, wdata.kb_idx, **COMMON)\n"
     "res_ss = minimize_spread(U_init, Mmn_opt, wdata.wb, wdata.bvecs, wdata.kb_idx,\n"
     "                        use_ss_functional=True, **COMMON)\n"
     "res_pm = minimize_spread(U_init, Mmn_opt, wdata.wb, wdata.bvecs, wdata.kb_idx,\n"
     "                        use_pm_functional=True, Aat=Aat_sub, atom_index=atom_index, **COMMON)\n"
     "\n"
     "Q_mv = compute_pm_spread(res_mv.U_final, Aat_sub, atom_index)[1]\n"
     "Q_ss = compute_pm_spread(res_ss.U_final, Aat_sub, atom_index)[1]\n"
     "Q_pm = compute_pm_spread(res_pm.U_final, Aat_sub, atom_index)[1]\n"
     "\n"
     "print(f'{\"functional\":6s} {\"Omega (Ang^2)\":>14s} {\"mean max(Q)\":>12s}')\n"
     "for name, res, Q in [('MV', res_mv, Q_mv), ('SS', res_ss, Q_ss), ('PM', res_pm, Q_pm)]:\n"
     "    omega_ang2 = res.Omega * BOHR_TO_ANG**2\n"
     "    print(f'{name:6s} {omega_ang2:14.4f} {Q.max(dim=1).values.mean().item():12.4f}')"),
    ("md", "### 4. Mulliken charges Q_A[n] per functional"),
    ("code",
     "fig, ax = plt.subplots(1, 3, figsize=(12, 4), dpi=150, sharey=True)\n"
     "for a, (name, Q) in zip(ax, [('MV', Q_mv), ('SS', Q_ss), ('PM', Q_pm)]):\n"
     "    im = a.imshow(Q.detach().numpy(), aspect='auto', cmap='viridis', vmin=0, vmax=1)\n"
     "    a.set_title(name); a.set_xlabel('atom'); a.set_xticks([0, 1])\n"
     "    fig.colorbar(im, ax=a, shrink=0.8, label='$Q_A[n]$')\n"
     "ax[0].set_ylabel('Wannier function $n$')\n"
     "fig.tight_layout()"),
    ("md", "**Takeaway.** MV and SS (near-identical $\\Omega_I$/$\\Omega_{OD}$, "
     "only $\\Omega_D$'s formula differs) give very similar Mulliken charge "
     "patterns and total spread — SS is a genuine alternative $\\Omega_D$ "
     "definition, not a dramatically different gauge in cases like this "
     "one without severe branch-cut pathology. PM is the outlier: its own "
     "optimization target has nothing to do with spatial compactness, and "
     "it shows — a *worse* (higher) ordinary MV spread than either MV or "
     "SS reach, traded for Wannier functions each concentrated almost "
     "entirely on a single atom (mean max Mulliken charge noticeably "
     "closer to 1 than MV/SS's own). That's the real, textbook PM-vs-MV "
     "tradeoff (Pipek & Mezey's own 1989 paper makes the same point for "
     "molecules): maximizing atomic character and minimizing spatial "
     "spread are different objectives, and there's no guarantee the same "
     "gauge optimizes both."),
]


