     "postw90 `berry_task=eval_shc`), applied to the SAME converged "
     "Bi₂Se₃ Wannier Hamiltonian as notebook 03 (rhombohedral $R\\bar3m$ "
     "strong topological insulator, 30 spinor MLWFs):\n"
