     "- **Qiao** (Qiao, Zhou, Yuan & Zhao, *PRB* **98**, 214402 (2018), "
     "\"QZYZ18\") — reconstructs the needed spin-decorated overlaps from "
     "the already-available `.mmn`+`.spn` via a completeness-insertion "
     "approximation. This is the method used by the official Wannier90 "
     "tutorials 29/30 (Platinum).\n"
