     "\"RPS19\") — uses genuine *ab-initio* `.sIu`/`.sHu` matrix elements "
     "one neighbour-shell away (`pw2wannier90`'s own `write_sIu`/"
     "`write_sHu`), avoiding Qiao's approximation entirely. **New "
     "capability this session** (`build_shc_ryoo_operators`, "
     "`_js_k_batch_ryoo`, confirmed against wannier90's own `develop`-"
     "branch source — not yet in any tagged release).\n"
     "\n"
     "**Why Bi₂Se₃, not Platinum** (the wannier90/WannierBerri tutorials' "
