     "USPP/PAW pseudopotentials in this QE version (`pw2wannier90.f90` "
     "errors explicitly), and this project's only relativistic Pt "
     "pseudopotential is PAW (PseudoDojo doesn't publish a norm-"
     "conserving fully-relativistic Pt). Bi₂Se₃'s Bi/Se pseudopotentials "
