    ("md", "### 3. The $D_3$ point group's 4 invariant tensors, from first principles\n"
     "SM25's own printed Eq. 8 lists the nonzero components of "
     "$\\epsilon^{ij}_{\\alpha a}$ ($\\alpha=1,\\ldots,4$) as a chain of "
     "\"=\" signs with no minus signs visible in the typeset PDF — almost "
     "certainly an OCR/typesetting artifact (superscript minus signs are "
     "commonly dropped), since e.g. $\\gamma^{ij}_{sa}$ built purely from "
     "the Levi-Civita symbol (the $\\alpha=1$ case, spin along $z$) is "
     "*manifestly* antisymmetric under $i\\leftrightarrow j$ by "
     "construction. Rather than trust a possibly-ambiguous transcription, "
     "the 4 tensors are derived here directly: build the actual $D_3$ "
     "point group (6 proper rotations: $E$, $C_3$, $C_3^2$, and 3 $C_2$ "
     "axes) and project the full rank-3 $(i,j,a)$ tensor space onto its "
     "group-invariant subspace. The result has exactly 4 invariant "
     "directions — matching SM25's own $n_\\alpha=(2,4,2,2)$ nonzero-"
     "component count exactly, a strong consistency check on the method "
     "itself."),
    ("code",
     "def _Rz(theta):\n"
     "    c, s = np.cos(theta), np.sin(theta)\n"
     "    return np.array([[c, -s, 0], [s, c, 0], [0, 0, 1]])\n"
     "\n"
     "def _d3_group():\n"
     "    C3, C2x = _Rz(2 * np.pi / 3), np.diag([1.0, -1.0, -1.0])\n"
     "    group, changed = [np.eye(3)], True\n"
     "    while changed:\n"
     "        changed = False\n"
     "        for g in list(group):\n"
     "            for h in (C3, C2x):\n"
     "                cand = g @ h\n"
     "                if not any(np.allclose(cand, e) for e in group):\n"
     "                    group.append(cand); changed = True\n"
     "    return group\n"
     "\n"
     "def _invariant_tensors(group):\n"
     "    P = np.zeros((27, 27))\n"
     "    for g in group:\n"
     "        P += np.einsum('ip,jq,ar->ijapqr', g, g, g).reshape(27, 27)\n"
     "    P /= len(group)\n"
     "    w, v = np.linalg.eigh(P)\n"
     "    basis = v[:, np.isclose(w, 1.0, atol=1e-8)]\n"
     "    return [basis[:, k].reshape(3, 3, 3) for k in range(basis.shape[1])]\n"
     "\n"
     "raw = _invariant_tensors(_d3_group())\n"
     "print(f'{len(raw)} invariant tensors found (SM25: n_alpha = (2,4,2,2), 4 total)')\n"
     "\n"
     "idx = {'x': 0, 'y': 1, 'z': 2}\n"
     "def _mk(comps):\n"
     "    T = np.zeros((3, 3, 3))\n"
     "    for i, j, a, val in comps:\n"
     "        T[idx[i], idx[j], idx[a]] = val\n"
     "    return T\n"
     "\n"
     "# normalize each raw tensor so its paper-listed leading component is +1\n"
     "EPS = [\n"
     "    _mk([('x', 'y', 'z', 1.0), ('y', 'x', 'z', -1.0)]),\n"
     "    _mk([('x', 'x', 'x', 1.0), ('y', 'y', 'x', -1.0), ('x', 'y', 'y', -1.0), ('y', 'x', 'y', -1.0)]),\n"
     "    _mk([('y', 'z', 'x', 1.0), ('x', 'z', 'y', -1.0)]),\n"
     "    _mk([('z', 'x', 'y', 1.0), ('z', 'y', 'x', -1.0)]),\n"
     "]\n"
     "N_ALPHA = [2, 4, 2, 2]\n"
     "# sanity check: each EPS[a] must actually lie in the span of the raw invariant basis\n"
     "raw_flat = np.stack([t.reshape(-1) for t in raw], axis=1)\n"
     "for a, eps in enumerate(EPS, start=1):\n"
     "    resid = eps.reshape(-1) - raw_flat @ (np.linalg.pinv(raw_flat) @ eps.reshape(-1))\n"
     "    print(f'eps_{a}: max residual outside the D3-invariant subspace = {np.abs(resid).max():.2e}')"),
