     "$(001)$ plane's Miller index in this primitive basis is **not** "
     "$(0,0,1)$. Solving $h\\,\\mathbf b_1+k\\,\\mathbf b_2+l\\,\\mathbf "
     "b_3 \\parallel \\hat z_\\mathrm{cubic}$ for integer $(h,k,l)$ gives "
     "$(1,1,0)$ — and `surface_transformation`'s resulting in-plane "
