     "kpath = np.vstack([seg(G, X, NSEG), seg(X, M, NSEG), seg(M, G, NSEG), [G]])\n"
     "ticks = [0, NSEG, 2 * NSEG, 3 * NSEG]\n"
     "labels = [r'$\\bar\\Gamma$', r'$\\bar X$', r'$\\bar M$', r'$\\bar\\Gamma$']\n"
