     "# ---- bare-perturbation ingredients (the UPFs' own radial data) -------\n"
     "PSEUDOS = [read_norm_conserving(PSEUDO_DIR / 'Mg.upf'),\n"
     "           read_norm_conserving(PSEUDO_DIR / 'B.upf')]\n"
     "TAU_FRAC = frac\n"
     "TYPES = np.array([0 if s == 'Mg' else 1 for s in syms])   # 0=Mg, 1=B\n"
