     "    omega_f, eigvec_f, masses_amu, types,\n"
     "    fermi_energy=E_FERMI, orbital_groups=GROUPS, omega_grid=omega_grid,\n"
     "    sigma_e=SIGMA_E, hr=hr,\n"
     ")\n"
     "lam_ij = elph.lambda_matrix(a2f_ij, omega_grid)\n"
     "\n"
     "print('lambda_ij   (row = k sheet i, col = k+q sheet j):')\n"
